use anyhow::Result;
use kzg::eth::eip_7594::{
    compute_cells_and_kzg_proofs_raw, compute_cells_raw, recover_cells_and_kzg_proofs_raw,
    verify_cell_kzg_proof_batch_raw,
};
#[cfg(feature = "arkworks")]
use rust_kzg_arkworks5::eip_7594::ArkBackend;
